solution.solution.cpp:
#include <cmath>
#include <vector>

struct Vec2 { double x; double y; };
struct Wall { double left; double top; double right; double bottom; };
enum class Outcome { Accepted, Clamped, Rejected };
struct MoveResult { Outcome outcome; Vec2 position; };

static bool insideAny(Vec2 p, const std::vector<Wall>& walls)
{
    for (const Wall& w : walls)
        if (p.x >= w.left && p.x < w.right && p.y >= w.top && p.y < w.bottom) return true;
    return false;
}

MoveResult validateMove(Vec2 previous, Vec2 reported, double dt, double maxSpeed, const std::vector<Wall>& walls)
{
    if (!(dt > 0.0) || !std::isfinite(reported.x) || !std::isfinite(reported.y))
        return { Outcome::Rejected, previous };

    const double dx{ reported.x - previous.x };
    const double dy{ reported.y - previous.y };
    const double distance{ std::sqrt(dx * dx + dy * dy) };
    const double limit{ maxSpeed * dt };

    MoveResult result{ Outcome::Accepted, reported };
    if (distance > limit * 1.01)
    {
        const double scale{ limit / distance };
        result = { Outcome::Clamped, { previous.x + dx * scale, previous.y + dy * scale } };
    }
    if (insideAny(result.position, walls)) return { Outcome::Rejected, previous };
    return result;
}

unitTests:
#include <cmath>
const std::vector<Wall> none{};
TEST("a normal move is accepted") { const auto r{ validateMove({ 0, 0 }, { 3, 4 }, 0.1, 60.0, none) }; CHECK(r.outcome == Outcome::Accepted); CHECK_NEAR(r.position.x, 3.0, 1e-9); CHECK_NEAR(r.position.y, 4.0, 1e-9); }
TEST("within the tolerance") { const auto r{ validateMove({ 0, 0 }, { 6.05, 0 }, 0.1, 60.0, none) }; CHECK(r.outcome == Outcome::Accepted); }
TEST("too far is clamped") { const auto r{ validateMove({ 0, 0 }, { 30, 40 }, 0.1, 60.0, none) }; CHECK(r.outcome == Outcome::Clamped); CHECK_NEAR(r.position.x, 3.6, 1e-9); CHECK_NEAR(r.position.y, 4.8, 1e-9); }
TEST("a teleport into a wall is rejected") { const auto r{ validateMove({ 0, 0 }, { 5, 0 }, 0.1, 60.0, { { 4, -1, 10, 1 } }) }; CHECK(r.outcome == Outcome::Rejected); CHECK_NEAR(r.position.x, 0.0, 1e-9); }
TEST("a clamped move that ends in a wall is rejected") { const auto r{ validateMove({ 0, 0 }, { 100, 0 }, 0.1, 60.0, { { 5, -1, 7, 1 } }) }; CHECK(r.outcome == Outcome::Rejected); }
TEST("the wall's right edge is outside it") { const auto r{ validateMove({ 0, 0 }, { 4, 0 }, 0.1, 60.0, { { 2, -1, 4, 1 } }) }; CHECK(r.outcome == Outcome::Accepted); }
TEST("bad input is rejected") { CHECK(validateMove({ 1, 1 }, { 1, 1 }, 0.0, 60.0, none).outcome == Outcome::Rejected); CHECK(validateMove({ 1, 1 }, { std::nan(""), 1 }, 0.1, 60.0, none).outcome == Outcome::Rejected); CHECK(validateMove({ 1, 1 }, { INFINITY, 1 }, 0.1, 60.0, none).outcome == Outcome::Rejected); }

